# Only unmanifested CPython cache generated by the 21:28:35-37 SDK probe.
param([switch]$Apply)
$ErrorActionPreference='Stop'
$tpRelease=(Resolve-Path -LiteralPath 'C:\Users\jaewo\AppData\Local\TwinPulse\installed\releases\20261024T120650Z-a57eece146d5').Path
$tpOutput='C:\Users\jaewo\Documents\TwinPulse\outputs\environment-photo-live-20261024-01'
$tpTarget=Join-Path $tpOutput 'cache-quarantine'
if(Test-Path -LiteralPath 'C:\Users\jaewo\AppData\Local\TwinPulse\runtime\launcher.lock'){throw 'EXIT_APP_FIRST'}
if(Get-Process -Id 30520 -ErrorAction SilentlyContinue){throw 'CLOSE_FAILED_STARTUP_DIALOG_FIRST'}
$tpManifest=Get-Content -LiteralPath (Join-Path $tpRelease 'windows-release-manifest.json') -Raw | ConvertFrom-Json
$tpNames=[System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach($tpEntry in $tpManifest.files){[void]$tpNames.Add($tpEntry.path)}
$tpRows=@()
foreach($tpFile in Get-ChildItem -LiteralPath $tpRelease -Recurse -File){
    $tpRelative=$tpFile.FullName.Substring($tpRelease.Length+1).Replace('\','/')
    if($tpRelative -eq 'windows-release-manifest.json' -or $tpNames.Contains($tpRelative)){continue}
    if(-not $tpRelative.StartsWith('_internal/resources/') -or $tpRelative -notmatch '/__pycache__/[^/]+\.cpython-312\.pyc$'){throw ('UNREVIEWED_EXTRA: '+$tpRelative)}
    if($tpFile.CreationTime -lt [datetime]'2026-10-24T21:28:35' -or $tpFile.CreationTime -gt [datetime]'2026-10-24T21:28:38'){throw 'UNREVIEWED_CREATION_TIME'}
    $tpAbsolute=[System.IO.Path]::GetFullPath($tpFile.FullName)
    $tpDestination=[System.IO.Path]::GetFullPath((Join-Path $tpTarget $tpRelative))
    if(-not $tpAbsolute.StartsWith($tpRelease+'\',[System.StringComparison]::OrdinalIgnoreCase) -or -not $tpDestination.StartsWith($tpTarget+'\',[System.StringComparison]::OrdinalIgnoreCase)){throw 'OUT_OF_SCOPE_PATH'}
    $tpAncestor=Get-Item -LiteralPath $tpAbsolute
    while($null -ne $tpAncestor -and $tpAncestor.FullName.Length -ge $tpRelease.Length){
        if($tpAncestor.Attributes -band [System.IO.FileAttributes]::ReparsePoint){throw 'REPARSE_TARGET'}
        $tpAncestor=if($tpAncestor.PSIsContainer){$tpAncestor.Parent}else{$tpAncestor.Directory}
    }
    $tpRows+=[pscustomobject]@{source=$tpAbsolute;target=$tpDestination;relative=$tpRelative;bytes=$tpFile.Length;sha256=(Get-FileHash -LiteralPath $tpAbsolute -Algorithm SHA256).Hash.ToLower();created=$tpFile.CreationTime}
}
if($tpRows.Count -ne 114){throw ('INVENTORY_COUNT_REVIEW_REQUIRED: '+$tpRows.Count)}
if(-not $Apply){$tpRows | ConvertTo-Json -Depth 3;exit 0}
if(Test-Path -LiteralPath $tpTarget){throw 'QUARANTINE_ALREADY_EXISTS'}
New-Item -ItemType Directory -Path $tpTarget | Out-Null
$tpRows | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $tpOutput 'cache-quarantine-inventory.json') -Encoding UTF8
foreach($tpRow in $tpRows){
    if((Get-FileHash -LiteralPath $tpRow.source -Algorithm SHA256).Hash.ToLower() -ne $tpRow.sha256){throw 'CACHE_CHANGED'}
    New-Item -ItemType Directory -Path ([System.IO.Path]::GetDirectoryName($tpRow.target)) -Force | Out-Null
    Move-Item -LiteralPath $tpRow.source -Destination $tpRow.target
    if((Get-FileHash -LiteralPath $tpRow.target -Algorithm SHA256).Hash.ToLower() -ne $tpRow.sha256){throw 'QUARANTINE_HASH_MISMATCH'}
}
[pscustomobject]@{status='QUARANTINED_NOT_DELETED';files=$tpRows.Count;bytes=($tpRows|Measure-Object bytes -Sum).Sum;target=$tpTarget} | ConvertTo-Json
